class Solution {
  public int countIslands(int[][] grid, int k) {
    int m = grid.length, n = grid[0].length, count = 0;
    boolean[][] seen = new boolean[m][n];
    int[] stack = new int[m * n];
    int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1};
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        if (grid[i][j] == 0 || seen[i][j]) continue;
        long sum = 0;
        int sp = 0;
        stack[sp++] = i * n + j;
        seen[i][j] = true;
        while (sp > 0) {
          int u = stack[--sp], x = u / n, y = u % n;
          sum += grid[x][y];
          for (int d = 0; d < 4; d++) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && ny >= 0 && nx < m && ny < n && grid[nx][ny] > 0 && !seen[nx][ny]) {
              seen[nx][ny] = true;
              stack[sp++] = nx * n + ny;
            }
          }
        }
        if (sum % k == 0) count++;
      }
    }
    return count;
  }
}
